# Union vs AND

# Try AND: 0 only where ALL odd rows have 0
output_and = []
for r in range(13):
    row = []
    for c in range(14):
        if c in [2, 5, 8, 11]:
            row.append(0)
        elif c in [1, 4, 7, 10, 13]:
            # Odd rows only
            if r % 2 == 1:
                val = input_grid[r][c]
            else:
                val = 6
            row.append(val)
        else:
            # For left cols, check if right col is 0 in ALL odd rows
            right_col = c + 1
            if r % 2 == 1:
                right_val = input_grid[r][right_col]
                if right_val == 0:
                    row.append(0)
                else:
                    row.append(6)
            else:
                row.append(6)
    output_and.append(row)
    print(f"AND Row {r}: {row}")

# Try OR: 0 where ANY odd row has 0
output_or = []
for r in range(13):
    row = []
    has_zero = False
    for odd_r in range(1, 13, 2):
        if input_grid[odd_r][c] == 0:
            has_zero = True
            break
    for c in range(14):
        if c in [2, 5, 8, 11]:
            row.append(0)
        elif r % 2 == 1:
            row.append(0 if has_zero else 6)
        else:
            row.append(6)
    output_or.append(row)
    print(f"OR Row {r}: {row}")

